function normalizeString(str) {
  let newStr = str.normalize('NFD').replace(/[\u0300-\u036f]/g,"")
  let string = newStr.replace(/["']/g, "").replace(/:\s*/g, " ").replace(/,/g, '').replace(/\//g, '').replace(/\?/g, '').replace(/\¿/g, '').split(' ').join('-').toLowerCase();
  return string;    
}

export default normalizeString;